-- public.rank_member_refusal(p_world uuid, p_founder uuid, p_uid uuid, p_power text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.rank_member_refusal(p_world uuid, p_founder uuid, p_uid uuid, p_power text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when p_uid = p_founder then null
    when not exists (select 1 from deed_member m
                      where m.world_id = p_world and m.founder = p_founder and m.uid = p_uid)
      then 'Not a citizen of ' || (select d.name from deed d where d.world_id = p_world and d.founded_by = p_founder) || '.'
    else rank_lacks(p_world, p_founder, p_uid, p_power) end
$function$
